package io.invenlio.inventory;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.time.Instant;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/inventory")@SecurityRequirement(name="bearerAuth")class ReservationController{private final ReservationService service;ReservationController(ReservationService s){service=s;}@Operation(summary="Create an exact-dimension inventory reservation",description="Requires inventory-reservation:manage and Idempotency-Key. Does not change the physical ledger.")@PostMapping("/reservations")ReservationService.ReservationView create(@RequestHeader(name="Idempotency-Key",required=false)String key,@Valid@RequestBody Request r){return service.create(key,new ReservationService.Command(r.referenceType,r.referenceId,r.variantId,r.warehouseId,r.locationId,r.lotId,r.serialId,r.quantity,r.expiresAt));}@Operation(summary="Read one reservation and its immutable allocations")@GetMapping("/reservations/{id}")ReservationService.ReservationView detail(@PathVariable UUID id){return service.detail(id);}@Operation(summary="Idempotently release an active reservation")@PostMapping("/reservations/{id}/release")ReservationService.ReservationView release(@PathVariable UUID id){return service.release(id);}@Operation(summary="List tenant reservations",description="Bounded filters with allow-listed createdAt, expiresAt, and status sorting.")@GetMapping("/reservations")List<ReservationService.ReservationView>list(@RequestParam(required=false)String status,@RequestParam(required=false)String referenceType,@RequestParam(required=false)String referenceId,@RequestParam(required=false)UUID variantId,@RequestParam(required=false)UUID warehouseId,@RequestParam(required=false)UUID locationId,@RequestParam(required=false)UUID lotId,@RequestParam(required=false)UUID serialId,@RequestParam(required=false)Instant expiringBefore,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)String sort){return service.list(status,referenceType,referenceId,variantId,warehouseId,locationId,lotId,serialId,expiringBefore,page,size,sort);}@Operation(summary="Aggregate on-hand, reserved, available and ATP",description="Available is mathematical on-hand minus reserved. ATP additionally excludes operationally ineligible dimensions.")@GetMapping("/availability")ReservationService.Availability availability(@RequestParam UUID variantId,@RequestParam(required=false)UUID warehouseId,@RequestParam(required=false)UUID locationId,@RequestParam(required=false)UUID lotId,@RequestParam(required=false)UUID serialId){return service.availability(variantId,warehouseId,locationId,lotId,serialId);}@Operation(summary="List eligible exact-dimension reservation candidates",description="Read-only deterministic FEFO-ready ordering; this endpoint does not allocate or reserve.")@GetMapping("/reservation-candidates")List<ReservationService.Candidate> candidates(@RequestParam UUID variantId,@RequestParam(required=false)UUID warehouseId,@RequestParam(required=false)String quantity,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.candidates(variantId,warehouseId,quantity,page,size);}@Operation(summary="Report reserved-projection mismatches",description="Bounded administrative diagnostic. Reservation allocations are authoritative; no repair is performed.")@GetMapping("/reservation-reconciliation")List<ReservationService.ReservationProjectionMismatch> reconciliation(@RequestParam(defaultValue="100")int limit){return service.reconciliation(limit);}record Request(@NotBlank String referenceType,@NotBlank@Size(max=128)String referenceId,@NotNull UUID variantId,@NotNull UUID warehouseId,@NotNull UUID locationId,UUID lotId,UUID serialId,@NotBlank String quantity,Instant expiresAt){}
}
